"""Original, scenario based Bulgarian curriculum briefs for Perfect Video modules 4–6."""

LESSONS = []
SUBTITLES = {
    "04": "Светлина и цвят — от сцена до надежден финален файл",
    "05": "Звук — запис, чистене и права",
    "06": "Подготовка и работа с хора — снимачен ден без гадаене",
}


def L(id, title, goal, hook, core, detail, deep, steps, case, bad, fix, check,
      limit, field, new_case, transfer, note, trap):
    assert len(steps) == 4
    LESSONS.append(locals() | {"subtitle": SUBTITLES[id[2:4]]})


# Модул 4: първо контролираш източника и експонацията; едва после обработваш цвета.
L("pv04-01", "Светлина от един прозорец", "Ще направиш повторяем портрет със светлина от прозорец и ще познаеш кога тя вече се променя.",
  "Прозорецът изглежда безплатен, докато облак не премести контраста по средата на интервюто.",
  "Гледай къде пада светлината върху лицето и фона, вместо да преследваш един задължителен ъгъл.",
  "Голям видим източник дава по-плавен ръб на сянката. Разстоянието и посоката променят съотношението лице–фон; бял картон връща светлина, черен картон поглъща отражения.",
  "Снимай 10 секунди при реалното време на деня и заключи експозиция и баланс на бялото. Изключи лампата на тавана само ако смесеният цвят пречи; оставена като умишлен фон, тя може да работи. Ако слънцето удря директно, тънък дифузен материал омекотява светлината, но не използвай плат до горещ източник. Запиши как ще реагираш, когато небето се смени.",
  ["Избери фон и позиция според светлината на лицето.", "Провери отраженията и сложи бял или черен картон според нуждата.", "Заключи камерата и заснеми кратък тест при реалното време.", "Повтори теста след промяна на облаците и сравни лицето."],
  "Пекарка разказва за работата си до западен прозорец. В първия дубъл облак прави лицето меко; след пет минути слънцето реже половината кадър. Имаш още три въпроса.",
  "Продължаваш със същите настройки, а после се опитваш да възстановиш изгоряла кожа в монтажа.",
  "Премести човека извън директния лъч или сложи дифузия; направи нов тест и снимай контролен кадър преди следващия отговор.",
  "Сравни замразени кадри от първия и последния дубъл при еднакъв изглед; провери светлите участъци и съотношението лице–фон.",
  "Няма универсална позиция на метър от стъклото. Посоката, размерът на прозореца, сезонът и облаците променят резултата.",
  "Работна задача без качване на файл: заснеми по 10 секунди без отражател, с бял картон и с черен картон. Запиши на кои кадри лицето е четимо и къде фонът губи детайл.",
  "Прозорецът е зад говорителя, а стаята е тъмна; местене на целия екип е невъзможно.",
  "Промени посоката на камерата или използвай налично отражение и измери лицето спрямо фона; ако няма достатъчно светлина, смени мястото или времето.",
  "Следи реалната светлина между дублите. Когато средата се промени, новият тест е част от работата, не признание за грешка.",
  "Пусни автоматичен баланс на бялото и се надявай той да изравни всички дубъли.")

L("pv04-02", "Минимален светлинен комплект, който решава проблем", "Ще избереш едно осветително тяло и модификатори според сцената, контакта и безопасността.",
  "Пълна чанта с лампи не помага, ако на място няма място за безопасен статив.",
  "Първо избери позиция на светлината; купувай мощност и модификатори едва след тест на реалната сцена.",
  "Една стабилна светлина, мек модификатор, надежден статив, захранване и черен или бял картон решават повече задачи от случаен набор RGB панели. Приеми ограничението на помещението и дистанцията до човека като част от решението.",
  "На малък снимачен терен окабеляването и товарът на стойката са производствен риск. Провери маркировките и инструкциите на производителя за захранване, монтаж и разстояние до плат или перде. Нискочестотното трептене на осветлението може да даде ленти или пулсации при конкретен затвор; виж го във видео проба при същата кадрова честота, а не само с очи.",
  ["Опиши сцена, размер на помещение и нужната площ светлина.", "Разположи една лампа и безопасен статив извън пътя на хората.", "Запиши проба със същите fps и затвор като проекта.", "Провери сенки, отблясъци, трептене и кабели преди снимки."],
  "Малък магазин иска интервю след затваряне. Пространството е тясно, има стъклена витрина и пътека към изхода; разполагаш с една лампа.",
  "Поставяш лампата на пътеката, гониш „кинематографичен“ контур и пропускаш отблясък във витрината.",
  "Изнеси стойката извън пътеката, промени ъгъла спрямо стъклото и заснеми проба с реалния затвор.",
  "В записа няма пречещ отражателен блясък, пулсации или кабел в прохода; говорителят се вижда ясно.",
  "Мощността на етикета не казва колко светлина ще стигне до лицето след модификатор; тествай в това помещение.",
  "Направи план с една лампа: снимай 10 секунди на мястото, маркирай безопасния маршрут, после същата проба с променен ъгъл. Сравни четимостта, а не цената на екипировката.",
  "Контактът на място е далече и клиентът иска да смениш позицията на масата.",
  "Преизчисли маршрута и захранването; ако кабелът трябва да пресече проход, промени плана и избери безопасна позиция.",
  "Задавай въпроса „Какво съществуващо препятствие премахва тази лампа?“. Ако нямаш отговор, не добавяй още една.",
  "Вдигни ISO и поправи отблясъците с цветна корекция.")

L("pv04-03", "Черно знаме: махни отражението, което разваля сянката", "Ще използваш отрицателно запълване и ще определиш кога то отнема твърде много детайл.",
  "Бяла стая връща светлина към лицето отвсякъде; още една лампа няма да върне обема.",
  "Черна повърхност от страната на сянката спира част от върнатата светлина и прави формата видима.",
  "Постави матов черен картон извън кадъра; мести го и гледай как се изменя сенчестата страна. Това не е „намаляване на експозицията“ на цялата сцена, а контрол на отражението в определена посока.",
  "Гланцирана или твърде малка повърхност може да не помогне. Отдръпни картона постепенно, докато окото в сянката остане четимо. Провери фона и дрехите: ако те потъват в черно, добави разстояние или промени ъгъла на ключовата светлина, вместо да стискаш контраста в монтажа.",
  ["Заключи експонация, баланс и основен кадър.", "Сравни кадъра без черна повърхност и с нея от страната на сянката.", "Мести картона, докато лицето запази нужния детайл.", "Провери очите и черната дреха на реален екран."],
  "Говорител с тъмно сако стои в бял офис. Лицето е плоско, но сакото лесно се слива със стената, когато добавиш черен картон.",
  "Слагаш голяма черна плоскост до самото лице и приемаш изгубеното око за „драматичен стил“.",
  "Отмести плоскостта, запази формата на лицето и върни малко отражение към сенчестото око, ако е нужно.",
  "На стоп кадър и двете очи са четими, а формата е по-ясна от оригинала; фонът остава отделен.",
  "Отрицателното запълване не спасява липса на светлина; при тъмна сцена може да влоши полезния сигнал.",
  "Запиши серия A/B при фиксирани настройки. Ако гласът и намерението са спокойни и доверителни, избери умерен контраст; ако сцената е напрегната, контрастът може да служи на историята.",
  "След това преместваш същата установка в малко тъмно помещение.",
  "Първо измери дали има достатъчно светлина върху лицето; използвай отрицателно запълване само ако има излишно отражение.",
  "Лицето носи смисъла. Изразителната сянка е успешна само когато зрителят вижда реакцията.",
  "Усили черния цвят в цялата картина и ще получиш същия локален ефект.")

L("pv04-04", "Контурна светлина без изгорели краища", "Ще отделиш човека от фона с контур и ще спреш светлината, преди да попадне в обектива.",
  "Контурът може да отдели рамото, но същата лампа може да измие целия кадър.",
  "Постави контурната светлина зад и встрани от субекта, като гледаш краищата и отблясъка едновременно.",
  "Флаг, решетка или промяна на ъгъла ограничава разлива към обектива. Не осветявай косата и рамото на максимума само защото има отделяне; търси разлика спрямо фона, която помага на читимостта.",
  "Запиши проба с включен и изключен контур. Провери дали бялата риза не губи текстура, дали светлината не реже носа и дали в очилата няма ярко петно. Ако фонът вече дава достатъчен цвят или тонален контраст, допълнителната лампа може да не е нужна. Контурът не заменя правилно осветено лице.",
  ["Настрой основния кадър и лицето без контур.", "Добави слаба светлина зад рамото и провери отраженията.", "Ограничи лъча или промени ъгъла, ако удари обектива.", "Сравни A/B на експортирания файл и остави по-ясния вариант."],
  "Снимаш интервю пред тъмни рафтове. Контурът отделя косата, но на широкия план образът става млечен.",
  "Вдигаш яркостта, докато косата свети в бяло; отблясъкът остава във всяка камера.",
  "Измести лампата, сложи флаг или решетка и намали мощността до видимо, но естествено отделяне.",
  "Широкият и близкият план пазят текстура в коса и дреха; черното отново изглежда черно.",
  "При голяма дистанция до фона или светъл фон отделянето може да е достатъчно и без контур.",
  "Сними три последователни варианта: без лампа, слаб контур и силен контур. Сравни не само косата, а и общия контраст на изображението.",
  "Говорителят сменя тъмното сако с лъскава бяла риза.",
  "Намали или премахни контура; провери дали бялата тъкан запазва детайл и дали широкият кадър не губи черното.",
  "Бърз тест: изключи контура. Ако никой не може да обясни какво точно се загуби, може да го оставиш изключен.",
  "Компенсирай липсващия контур със силно изостряне в монтажа.")

L("pv04-05", "Мотивирана светлина: кадърът да има причина", "Ще изградиш осветление, което изглежда естествено за мястото и служи на историята.",
  "Лампа в кадъра обещава топла светлина; ако лицето свети студено от обратната страна, зрителят усеща измамата.",
  "Всяка видима светлина предполага посока. Нека основният източник продължи това, което зрителят вече вижда в сцената.",
  "Нощна лампа, прозорец или отворена врата може да е визуално обяснение за светлина извън кадър. Не е задължително практическата лампа сама да осветява лицето; важно е посоката, цветът и яркостта да не си противоречат.",
  "Изключи всички лампи и виж каква светлина идва от мястото. После включвай източник по източник и наблюдавай сенките. Ако фонова лампа изгаря абажура, намали експозицията ѝ или смени крушката, без да потапяш лицето в тъмно. Заключи баланса на бялото и снимай срещуположните планове със същата логика на посоката.",
  ["Посочи видимия или предполагаем източник в сцената.", "Подреди основната светлина така, че сянката да има логична посока.", "Настрой отделно лицето и практическата лампа.", "Снимай план и обратен план; провери дали светлината пази една история."],
  "Готвач разказва пред топла настолна лампа, но голям LED осветява лицето от страната, която лампата не може да достигне.",
  "Добавяш още две цветни лампи и прикриваш несъответствието с оранжев филтър.",
  "Премести основния източник в логичната посока на лампата или направи прозорецът ясно видим като втора причина.",
  "И двата плана показват една и съща логика на сенките; кожата е четима и абажурът пази детайл.",
  "Мотивирано не значи буквално. Светлината може да е усилена извън кадър, стига сцената да остане убедителна.",
  "Начертай със стрелки посоките на видимите източници и на сенките. Прегледай един статичен кадър без звук: зрителят трябва да разбира откъде идва светлината.",
  "Екипът премества разговора по-близо до дневен прозорец.",
  "Избери водещия източник наново; ако прозорецът вземе сцената, остави настолната лампа като фонов акцент.",
  "Осветлението разказва за мястото. Истинската проверка е дали след монтажа плановете още изглеждат от една стая.",
  "Остави всички източници на максимална яркост, за да няма тъмни участъци.")

L("pv04-06", "Смесена светлина и постоянен цвят", "Ще разпознаеш кога два източника дават различен цвят върху едно лице и ще решиш проблема на терен.",
  "Половината лице е синкава дневна светлина, другата е жълта от тавана; плъзгачът за баланс няма как да поправи и двете наведнъж.",
  "Един баланс на бялото избира една опорна точка. Първо реши кои източници ще осветяват лицето.",
  "Можеш да изключиш, покриеш или преместиш нежелан източник, да групираш лампите с близък цвят или умишлено да оставиш контраст в отделен фон. Цветната температура не описва напълно спектъра на една лампа.",
  "Постави неутрален предмет или референтна карта при светлината върху лицето, а не на произволно място в стаята. Заключи баланса след проба и гледай кожата и цветните предмети. При светодиоди с различен спектър две лампи със сходни Kelvin стойности пак може да дадат различни кожи; сравни записа от самата камера, вместо да разчиташ на числото.",
  ["Определи водещия източник за лицето.", "Ограничи вторичната светлина или я остави само във фона.", "Заключи баланса на бялото при реалната светлина.", "Снимай и сравни кожа и неутрален предмет в двата плана."],
  "Снимаш фризьорски салон: голяма витрина отляво, топли спотове над клиентката и студено огледало отпред.",
  "Коригираш целия кадър към неутрално и оставяш зеленикави петна по едната буза.",
  "Изключи или отслаби проблемния спот върху лицето, избери един водещ източник и настрой ръчен баланс след проба.",
  "Кожата няма два противоречиви цвята; при смяна на план не се появява внезапен цветен скок.",
  "Различен цвят във фона може да е творчески избор. Проблемът е противоречивият цвят върху една и съща важна повърхност.",
  "Запиши 10 секунди с всички лампи и още 10 с една изключена. Стопни кадъра на кожа и бял предмет и сравни; записът е по-надежден от обяснение на хартия.",
  "Настъпва залез и дневната светлина отслабва по време на интервюто.",
  "Преоцени водещия източник, направи нов ръчен баланс и остави контролен кадър за цветно съвпадение.",
  "„Същите Kelvin“ на етикета са начало за проба, а не гаранция за еднакъв резултат.",
  "Прехвърли всички камери на автоматичен баланс и остави всяка да решава самостоятелно.")

L("pv04-07", "CRI е показател, не присъда за кожата", "Ще сравниш две лампи в камерата и ще знаеш какво CRI не ти казва.",
  "Купуваш осветление с високо CRI, а червеният продукт пак изглежда мъртъв.",
  "Оцени лампата по реален запис на кожа и фирмени цветове; числото на кутията само насочва кои да тестваш.",
  "CRI описва определен тест спрямо референтен източник, но не гарантира как всеки цвят или всяка камера ще реагира. При различни диоди и режими спектърът, зеленото отклонение и цветните наситени повърхности може да се различават.",
  "Заключи експонация и баланс на бялото, снимай една и съща сцена с една лампа, после смени само лампата. Гледай кожа, червен и син предмет, бял лист и сиви сенки. Ако производителят публикува и други метрики, разгледай ги, но не превръщай нито една в обещание за крайна снимка. Смесването на две различни лампи се проверява отделно.",
  ["Избери една и съща сцена и цветни предмети.", "Заключи камерата и позицията на лампата.", "Запиши A/B с двата източника при сравнима яркост.", "Провери кожа, наситени цветове и сенки на еднакъв екран."],
  "Снимаш червена опаковка на бонбони за каталог. Два панела пишат CRI 95; при единия продуктът губи разликата между червено и оранжево.",
  "Обявяваш двата панела за еднакви по спецификация и поправяш всеки кадър с различен LUT.",
  "Направи контролна проба с продукта и избери лампата, която възпроизвежда нужните цветове последователно.",
  "Двата файла са със същите настройки; цветът на опаковката и кожата се различават видимо и изборът е повторяем.",
  "Няма универсално минимално CRI, което да гарантира правилна кожа при всички камери и спектри.",
  "Снимай едно лице и два продуктови цвята с лампата на различни мощности; сравни и приглушения режим, защото спектърът и пулсациите може да се променят.",
  "Клиентът добавя в кадър ярко лилава опаковка.",
  "Направи нова проба именно с лилавата повърхност и финалната комбинация лампа–камера.",
  "Спецификацията помага за подбор. Решението се взема по контролирана проба от сцената, която клиентът реално ще получи.",
  "Вдигни сатурацията, докато опаковката изглежда „по-цветна“ на камерата.")

L("pv04-08", "Три сцени, три решения за светлина", "Ще пренаредиш една лампа за интервю, продукт и влог, без да прилагаш една схема навсякъде.",
  "Светлина, която ласкае лице, често скрива релефа на опаковка или блести в чашата.",
  "Сменяй посока, размер и дистанция според това какво зрителят трябва да види.",
  "За интервю провери очите и фона; при продукт провери текстура, отблясъци и надпис; при влог провери как лицето остава четимо при движение. Една лампа може да остане същата, но задачата ѝ се сменя.",
  "Големият мек източник разширява отражението върху лъскав предмет; тесен източник може да покаже текстура по-рязко. При самозаснемане маркирай допустимата зона на движение на пода и направи проба в двата края. Не подреждай оборудването по любима диаграма, ако резултатът не служи на обекта.",
  ["Запиши една цел: лице, надпис или движение.", "Разположи лампата и фона според тази цел.", "Сними проба и провери ръбове, отблясък и сенки.", "Промени едно условие и повтори теста за следващата сцена."],
  "Екип снима собственик на кафене, после лъскав буркан и накрая кратък влог, докато той върви между масите.",
  "Оставяш осветлението на едно място и приемаш отражение, което заличава името на буркана.",
  "За продукта премести източника така, че отражението да очертава форма, но да освободи етикета; за влога ограничи движението или промени мястото.",
  "Името се чете на продукта, очите се виждат в интервюто, а лицето не потъва в сянка при движение.",
  "Няма универсална схема с един ъгъл: материалът, повърхността и движението определят позицията.",
  "С една лампа сними три 10-секундни клипа. За всеки назови една грешка и една промяна; приеми само вариант, който изпълнява предварително избрания критерий.",
  "Бурканът се заменя с матова кутия с релефен печат.",
  "Тествай по-странична светлина за релефа и запази четимостта на печата; не пренасяй ъгъла от лъскавия буркан механично.",
  "Няколко различни задачи могат да се снимат с един комплект, ако променяш позицията, а не очакванията на клиента.",
  "Добави още лампи преди да провериш отблясъка.")

L("pv04-09", "Цветова корекция преди визия", "Ще поправиш експонация и баланс преди да правиш стилистичен цвят.",
  "Красив LUT върху неправилен баланс прави грешката по-красива и по-трудна за откриване.",
  "Раздели нормализиране на материала, изравняване на плановете и стилистичната визия.",
  "Първо избери правилен вход и изход за материала. После настрой експонация, контраст и баланс по образа и измервателните инструменти. Едва след това добави творческата промяна.",
  "Използвай референтен кадър от същата сцена, но не изтривай умишлена нощна атмосфера с автоматично „избелване“. Ако екранът не е надежден, гледай waveform и RGB parade за крайности и сравнявай на още едно устройство. Запази версия преди визията, за да можеш да отделиш технически проблем от стил.",
  ["Провери входния цветови профил и целевия изход.", "Изправи експонация и баланс без творчески филтър.", "Изравни съседните планове с референтен кадър.", "Добави визия и провери на целевия екран."],
  "Кафене получава два кадъра от една сцена: едната камера е студена, другата топла. Иска се мек филмов тон.",
  "Слагаш един и същ LUT на двата клипа и оставяш кожата да сменя цвят при срез.",
  "Нормализирай входа на всяка камера, изравни кожа и експонация, после приложи обща визия с проверка при срез.",
  "При прехвърляне между кадрите кожата и неутралните предмети не скачат; визията не клипва светлите зони.",
  "Не всяка сцена има неутрално бяло. Следвай намерението и контролния кадър, не автоматична стойност.",
  "Направи два експорта: чист коригиран и стилизиран. Ако грешката се появява и в чистия, върни се към техническата корекция.",
  "Клиентът одобрява стила, но иска продукта по-близо до реалния му цвят.",
  "Запази одобрената обща визия и поправи локално продукта с проверка срещу референтен кадър.",
  "„Технически правилно“ е основа за последователност, а стилът е решение за конкретен разказ.",
  "Добави наситеност към всички цветове, докато продуктът се доближи до каталога.")

L("pv04-10", "Топъл и студен цвят: решение за историята", "Ще тестваш настроение с цвят, без да подменяш бранд или естествени предмети.",
  "Оранжевият кадър може да е уютен, но също може да направи синята опаковка кафява.",
  "Настроението идва от сцената, светлината и монтажа заедно; температурата сама не обещава определена емоция.",
  "Избери какво трябва да усеща зрителят, какво трябва да разпознае и кои цветове са неприкосновени. Направи два варианта от един и същ неутрален кадър, вместо да сравняваш различни кадри.",
  "Гледай кожата, фирмения цвят и неутрален предмет при двата варианта. Покажи ги в контекста на съседните кадри и звука. Ако разказът е за свежест, топлият вариант може да му противоречи; ако клиентът продава физически продукт, значимите цветове не бива да се измислят.",
  ["Определи посланието и предметите, чиито цветове трябва да останат честни.", "Изготви неутрален референтен кадър.", "Направи два умерени варианта само от него.", "Прегледай ги в последователността на видеото с клиента."],
  "Пекарна иска „топло, домашно“ видео. Първата версия прави хляба оранжев, но маслото и бялата опаковка изглеждат неверни.",
  "Усилваш топлината до максимум, защото „топло продава“.",
  "Задръж уютното усещане чрез фон и светлина, но върни опаковката и храната към убедителни цветове.",
  "Двата варианта имат ясна разлика в настроение; важните продукти остават разпознаваеми.",
  "Една асоциация с цвят не е универсална за всяка аудитория или марка; провери реакцията в реалния контекст.",
  "Покажи A/B на двама души без да им подсказваш „топло“ и „студено“. Попитай какво различават в продукта и доверието към кадъра, а не кой филтър харесват.",
  "Същото видео ще се използва и за техническа инструкция.",
  "Остави по-неутрална, ясна версия за инструкцията; провери дали материалите и предупрежденията не се губят.",
  "Стилът не трябва да се бори с задачата на видеото.",
  "Промени температурата на всички кадри на една и съща стойност без сравнение.")

L("pv04-11", "Кожата като ориентир, не като шаблон", "Ще проверяваш кожен тон с контекст и ще избягваш универсална стойност за всички хора.",
  "Плъзгачът казва „правилно“, а лицето изглежда сиво или прекалено оранжево.",
  "Оцени кожата във връзка със светлината, човека и съседните кадри; не настройвай всички лица към един цвят.",
  "Vectorscope може да подскаже нежелан цветен уклон, но линията за кожа не определя светлота или желания вид за всеки човек. Маска върху малка зона може да помогне да прочетеш посоката, без да променяш целия кадър.",
  "Започни с правилен входен профил и баланс на бялото. Сравни лице, бял/сив предмет под същата светлина и референтен кадър от снимачния ден. Ако светлината е умишлено цветна, не изравнявай всяка буза към неутрално; поправи неволен зелен или магента оттенък само когато нарушава достоверността.",
  ["Нормализирай материала и намери референтен кадър.", "Провери кожата и неутралния предмет под една и съща светлина.", "Коригирай нежелания уклон умерено; пази текстура.", "Прехвърли между плановете и провери на друг екран."],
  "Двама служители са снимани в една стая, но единият стои под зеленикав LED. След обща корекция неговото лице още изглежда болно.",
  "Издърпваш глобално всички лица към една оранжева стойност.",
  "Коригирай конкретния кадър и източника на зеления уклон; сравни със същия човек в друг план.",
  "Лицето остава естествено за човека и светлината; кожата не сменя неволно оттенък при срез.",
  "Различните тонове кожа и умишленото цветно осветление не се побират в един универсален target на vectorscope.",
  "Сравни същото лице в два съседни плана, а не две различни лица като „един еталон“. Документирай коя лампа е светила всеки план.",
  "Оказва се, че финалният кадър е заснет под цветна сценична светлина.",
  "Запази умишления цвят на сцената и търси само неволни зелени/магента смени спрямо съседните кадри.",
  "Кожата е ориентир за непрекъснатост, не инструмент за уеднаквяване на хората.",
  "Кликни автоматично „skin tone“ и копирай стойностите на всички говорители.")

L("pv04-12", "Waveform и vectorscope: виж проблема, не гадай", "Ще откриваш изгубен детайл и цветен уклон чрез измервателните инструменти.",
  "Мониторът изглежда добре, но експортът губи белия текст на опаковката.",
  "Waveform показва разпределението на яркостта по изображението, vectorscope показва посока и сила на цвета.",
  "Чети scopes заедно с кадъра. Плоска линия в горния край на waveform може да е клипинг; силно изнесена точка на vectorscope може да е наситен предмет, не „грешка“. RGB parade помага да видиш разминаване между канали в неутрални области.",
  "Увери се, че гледаш правилното място във веригата на color management: лог сигнал преди трансформация изглежда различно от финалния изход. Провери отделно оригинал, коригирана версия и експорт. Никоя графика не заменя решение за съдържанието; тя показва какво се случва със сигнала.",
  ["Определи дали измерваш входа или финалния изход.", "Намери конкретно място в кадъра, което изглежда проблемно.", "Сравни waveform, vectorscope и изображението след една промяна.", "Изнеси тестов файл и повтори проверката върху него."],
  "Видео на шоколадов десерт има бяла чиния и червено лого. На лаптопа изглежда красиво, но на телефона чинията е без текстура.",
  "Вярваш само на яркостта на лаптопа и добавяш още контраст.",
  "Провери waveform за затисната светла област, намали прекомерната корекция и отвори експорта на целевия екран.",
  "Чинията пази форма, логото остава четимо, а scopes и експортираният файл не си противоречат.",
  "Стойностите на scopes зависят от цветното пространство, трансформацията и настройките на проекта.",
  "Пусни сравнителен кадър от финалния файл. Запиши кое е клипнато, къде е маскирано и кое е умишлено ярко.",
  "Получаваш Log материал от втора камера и waveform изглежда сплескан.",
  "Провери входната трансформация и оцени scopes на правилния етап преди да „поправяш“ сигнал, който е нормален за Log.",
  "Гледай измерванията като доказателства за конкретен въпрос, не като рецепта за еднакви графики.",
  "Премести всички нива така, че графиката да докосва и двата края.")

L("pv04-13", "Rec.709 и Log: една чиста цветна верига", "Ще организираш вход, обработка и изход без двойна трансформация и изгубен контраст.",
  "Материалът изглежда сив; слагаш LUT, после още един и лицето става пластмасово.",
  "Запиши какъв е реалният профил на всеки файл, в кое пространство работиш и към какъв екран изнасяш.",
  "Log е начин за кодиране на картината, а не готов финален вид. Превръщането към Rec.709 може да стане с подходящо color management или с правилна трансформация; ако приложиш и двете като еднакви стъпки, често удвояваш контраста и цвета.",
  "Провери точния профил в настройките на камерата или файловите метаданни; „Log“ не е една универсална крива. Използвай официалната трансформация за конкретната камера и поддържай последователен изходен target. Сравнявай референтна снимка от терена и финиширай на реален екран, защото превюто на монтажната програма може да следва друга дисплейна настройка.",
  ["Идентифицирай профила и gamut за всеки източник.", "Избери една работна схема: color management или ръчно управлявани трансформации.", "Коригирай експонация и баланс на нормализиран образ.", "Изнеси Rec.709 тест и провери кожа, светли и тъмни области."],
  "Един клип е заснет в Log, вторият е готов стандартен профил. Монтажът автоматично управлява цвета, а върху първия вече има технически LUT.",
  "Слагаш същия технически LUT и на двата файла, за да са „еднакви“.",
  "Провери входния профил на двата клипа; премахни дублираната трансформация и нормализирай всеки само веднъж.",
  "В изнесения файл кожата е непрекъсната и светлите детайли не се затварят след трансформация.",
  "Някои LUT файлове са творчески, други технически; името „cinematic“ не е описание на вход и изход.",
  "Направи контролен експорт на проблемния кадър с и без допълнителния LUT. Ако картината става прекалено контрастна, проследи веригата от входа до изхода.",
  "Получаваш клип без достоверни метаданни от трета камера.",
  "Поискай или провери настройката от снимачния ден и направи тест с референтен кадър; не приписвай профил по външен вид.",
  "Документирай веригата до конкретен вход и конкретен изход, за да може друг човек да отвори проекта без гадания.",
  "Вдигни контраст ръчно, докато сивият клип изглежда цветен.")

L("pv04-14", "Съвпадение между кадри, преди да личи срезът", "Ще сравниш два плана по експонация, баланс и важни цветове, без да ги правиш изкуствено еднакви.",
  "Снимките са красиви поотделно, но при монтаж чашата и лицето сменят цвят през секунда.",
  "Избери контролен кадър и сравнявай планове в един и същ контекст, преди да копираш настройки.",
  "Гледай общите предмети, лице, фон и посока на светлината. Първо изравни най-видимото разминаване в експонацията, после баланса и цвета. Прескачай между кадрите с кратък интервал, за да усетиш внезапния скок.",
  "Ако камерата се е обърнала към прозорец, двата плана имат естествено различна светлина. Целта не е числено съвпадение на всяка пикселна стойност, а зрителят да не се обърка от неволна смяна. Корекцията на кожа не трябва да унищожава истинския цвят на продукта. Запази неподправен референтен still преди силна визия.",
  ["Избери референтен кадър от същата сцена.", "Сравни експонация и неутрални предмети.", "Промени цветния уклон само в проблемния план.", "Прегледай среза на цял екран и в експорт."],
  "На интервю основната камера показва топло лице, близкият план е зеленикав. В кадъра и на двете има бяла чаша.",
  "Копираш стойностите на първата камера върху втората без да погледнеш оригиналния ѝ профил.",
  "Нормализирай входа на близкия план, ползвай чашата за ориентир и провери лицето при реалния срез.",
  "Срезът не сменя неволно цвета на лицето или чашата и не губи умишлената посока на светлината.",
  "Две камери с различен спектър или светлина няма да съвпаднат чрез copy/paste на плъзгачи.",
  "Монтирай пет бързи редувания между двата кадъра. Ако някой забелязва неволен цветен пулс преди думите, върни се към изходните трансформации.",
  "При снимането облак е затъмнил втория план, а човекът е преместен до лампа.",
  "Провери кой проблем е експонация и кой е нова посока на светлина; компенсирай четимостта, без да симулираш невъзможен идентичен модел.",
  "Съвпадението е непрекъснатост на разказа, не упражнение по еднакви числа.",
  "Уеднакви всички кадри по обща стойност на Kelvin.")

L("pv04-15", "Изгради визия, която преживява целия монтаж", "Ще създадеш умерен стил и ще го провериш върху най-трудния кадър, не само върху най-хубавия.",
  "Твоят любим кадър изглежда отлично; следващият със светла риза и тъмна кожа се разпада.",
  "Добрата визия трябва да издържи различни лица, материали и планове в една история.",
  "Остави отделни етапи за техническа корекция и творческа визия. Избери два или три контролни кадъра: лице, продукт и крайно осветление. Настрой визията върху тях, вместо да копираш силна настройка по цялата времева линия.",
  "Насищането на сенките и цветовете във високите светлини често изглеждат впечатляващи в един стоп кадър, но губят информация в движение. Следи за клипинг, шум и ленти при силни градиенти. Сравни преди/след на финален размер и в кратка последователност, защото усещането за стил се променя при монтаж.",
  ["Коригирай технически три различни контролни кадъра.", "Избери каква промяна подкрепя посланието.", "Приложи умерена визия и коригирай отделните кадри.", "Изнеси кратка последователност и провери най-трудния кадър."],
  "Филм за работилница включва слънчев вход, тъмно интервю и близък план на меден продукт. Силният стил прави продукта червен и убива сенките.",
  "Показваш само слънчевия вход и обявяваш визията за завършена.",
  "Намали крайностите, тествай и трите сцени и настрой отделно кадъра с продукта преди одобрение.",
  "Краткият експорт пази лицето, текста върху продукта и важен детайл в сянката във всички три сцени.",
  "Еднакъв LUT не гарантира еднакъв стил върху кадри с различен вход и светлина.",
  "Направи 20-секунден монтаж от трите най-трудни плана и гледай на целевия телефон. Запиши коя визия издържа всички, не коя печели един кадър.",
  "Появява се архивен клип от друг фотоапарат.",
  "Нормализирай го към работната схема и провери дали стилът не разкрива шум или клипинг; ако трябва, използвай по-лек вариант.",
  "Визията принадлежи на целия филм. Най-красивият кадър е лош тест за устойчивост.",
  "Копирай една силна настройка върху всичко и прегледай само първия кадър.")

L("pv04-16", "Teal и оранжево без пластмасова кожа", "Ще направиш разделяне на топло и студено, като запазиш кожа, продукт и естествена светлина.",
  "Популярна визия може да превърне всяко лице в един и същ оранжев тон.",
  "Топъл субект и по-студен фон може да дадат отделяне, ако сцената и марката позволяват това.",
  "Започни с чиста корекция и избери ограничени области, вместо да завъртиш глобално всички сенки към синьо. Пази белите предмети и корпоративните цветове; не всяка сянка е синя и не всяка кожа трябва да е оранжева.",
  "Избери кадър с лице, кадър с продукт и кадър със смесена светлина. Изгради лек вариант, после силен само за сравнение. При близък план следи порите, текстурата на косата и естествената разлика между хората. Ако корекцията работи само когато увеличиш сатурацията до край, тя вероятно не решава историята.",
  ["Нормализирай входа и избери референтна сцена.", "Отдели фон и субект с умерени промени.", "Провери кожа, бели предмети и фирмени цветове.", "Прегледай срезовете на целевия екран и запази по-честния вариант."],
  "Видео за лекарски кабинет получава синкави сенки и силно оранжеви лица. Клиентът казва, че изглежда като екшън, а не като доверен разговор.",
  "Защитаваш стила с аргумента, че така изглеждат „професионалните видеа“.",
  "Върни умерена неутралност в кожата и фона; ако студеният акцент остава, остави го само там, където подкрепя посланието.",
  "Човекът и услугата изглеждат достоверни; студеният фон не прави бялото синьо.",
  "Teal и оранжево е творческа възможност, а не стандарт за всеки жанр, бранд или тон кожа.",
  "Покажи клиентски A/B с неутрална и стилизирана версия без етикетите „аматьорско“ и „професионално“. Попитай кое по-добре носи доверието на видеото.",
  "Същият материал ще се ползва в продуктова реклама с синя опаковка.",
  "Пази разпознаваемия син цвят на продукта и оцени дали този стил изобщо е подходящ за продуктова версия.",
  "Изборът на визия зависи от работа, която видеото трябва да свърши.",
  "Оцвети всички тъмни пиксели в синьо и всички средни в оранжево.")

L("pv04-17", "Финален проект: една сцена, три честни версии", "Ще заснемеш една сцена и ще предадеш три сравними версии с доказуем избор на светлина и цвят.",
  "Три филтъра върху различни кадри не доказват, че можеш да контролираш светлината.",
  "Използвай един и същ кратък разговор и запази ясна връзка между светлината на терен, техническата корекция и стила.",
  "Версия А показва чистата сцена; Б променя светлината или отраженията; В добавя умерена цветна визия след нормализиране. Постави един и същ важен предмет и лице във всички сравнения.",
  "Запиши експонация, баланс, позиция на източника и какво си променил между вариантите. Не подменяй речта и кадрирането толкова, че сравнението да стане нечестно. Проверявай клипинг, кожа, отблясък и бранд цвят върху експортирани файлове. При провал избери варианта, който изпълнява задачата, дори да е по-скромен.",
  ["Заснеми базов кратък кадър и контролен still.", "Промени един светлинен фактор и запиши втори вариант.", "Коригирай технически, после направи отделна стилова версия.", "Изнеси A/B/C и сравни по предварително записани критерии."],
  "Малка сладкарница иска 20 секунди за нов продукт. Версия А е четима, Б добавя контраст със черен картон, В прави продукта неестествено червен.",
  "Избираш В, защото най-силно привлича окото, без да погледнеш истинския продукт.",
  "Върни фирмения цвят и остави контраста от Б; изнеси трите файла и покажи защо избираш финалния.",
  "Има три експорта от сравнима сцена; лицето и продуктът са четими и изборът може да се обясни с наблюдаем резултат.",
  "Няма универсално най-добър вариант; целта и ограниченията на конкретния клиент решават.",
  "Изпълни проекта с телефон или камера и един прозорец/лампа. Сравнявай финалните файлове, не екранни снимки от различни приложения.",
  "Клиентът сменя целта: видеото трябва да служи и като продуктова инструкция.",
  "Прегледай трите версии за точност на продукта и четимост на демонстрацията; избери или адаптирай най-ясната.",
  "Проектът е завършен, когато можеш да покажеш както творческия избор, така и границите му.",
  "Предай само най-ефектния файл без контролно сравнение.")


# Модул 5: гласът се спасява при записа; монтажът може да подобри, не да измисли липсващи думи.
L("pv05-01", "Слушай преди да включиш камерата", "Ще откриеш шум, реверберация и повреден запис с кратка слушателска проба.",
  "Изображението е остро, но хладилникът заглушава цялото интервю.",
  "Затвори очи и слушай мястото за глас, тишина и внезапни звуци, преди да фиксираш кадъра.",
  "Слушай с надеждни слушалки директно от записващото устройство, не само от монитора на камерата без аудио. Отдели постоянен шум, отражения на стаята и случайни събития като врата или телефон.",
  "Запиши 20 секунди нормална реч и поне 10 секунди тишина на същото място. Сравни какво се чува при паузите и под думите. Реверберацията не се решава със същия бутон като постоянен шум; най-евтината поправка често е да доближиш микрофона и да смениш позицията. Ако екипът трябва да остане на мястото, отбележи рисковите звуци в снимачния план.",
  ["Слушай помещението в тишина и назови три конкретни звука.", "Запиши кратка реч и тишина с избрания микрофон.", "Пусни пробата през слушалки от устройството.", "Промени място или позиция и повтори при същия глас."],
  "Собственик на фурна говори ясно, но по време на пробата фурната включва вентилатор на всеки няколко минути.",
  "Пропускаш пробата, защото шумът ще се „махне с AI“.",
  "Уговори паузи за шумния цикъл или премести разговора; дръж микрофона по-близо и запиши нова проба.",
  "В паузите и под тихите думи гласът остава разбираем; вентилаторът не променя звученето между дублите.",
  "Кратката проба не гарантира, че шумът няма да се появи по-късно; слушай и по време на снимките.",
  "Направи две проби на същия глас: в центъра на стаята и близо до меки повърхности. Изравни силата при сравнение, за да оценяваш акустиката, не по-силния файл.",
  "Вратата към улицата трябва да остане отворена за работата на обекта.",
  "Промени ориентацията на микрофона и времето на запис; ако шумът заглушава думите, уговори друго място.",
  "Тишината между репликите е част от материала. Ако тя е различна при всеки дубъл, монтажът ще разкрие срезовете.",
  "Усили гласовия канал до максимум, за да скриеш реверберацията.")

L("pv05-02", "Петличка, насочен или вграден микрофон?", "Ще подбереш микрофон според разстояние, движение, дрехи и среда.",
  "Скъп насочен микрофон от три метра записва по-ясно стаята, отколкото гласа.",
  "Положението на микрофона и прякото звучене на гласа често имат по-голям ефект от името на модела.",
  "Петличката следва движещ се говорител, но може да търка дреха. Бумът стои извън кадър и дава естествен глас, ако може да се държи близо. Вграденият микрофон е резервен или синхронизиращ източник, когато камерата е далеч.",
  "При петличка направи тест при истинските движения и дрехи; проверявай триене, бижута и проводник. При бум провери дали микрофонът остава насочен към устата, а не към отразяваща стена. Ако снимачният план се променя, резервен канал или втори запис може да спаси интервюто само ако е бил проверен преди снимките.",
  ["Опиши движение, кадриране и облекло.", "Постави наличния микрофон възможно най-близо без да влиза в кадър.", "Запиши реч при реалните движения и слушай за триене.", "Избери основен и проверен резервен източник."],
  "Говорител в работилница се навежда над маса. Петличката е скрита под яке, а насоченият микрофон е закрепен върху камерата на два метра.",
  "Оставяш микрофона на камерата като „професионален shotgun“ и приемаш кухия звук.",
  "Премести насочения микрофон близо над кадъра или закрепи петличката без триене; прослушай реалното движение.",
  "В цялото навеждане речта остава разбираема и няма силно търкане на плат.",
  "Насоченият микрофон не премахва ехо, когато е твърде далеч; полярният модел има граници.",
  "Запиши една и съща фраза с вграден, петличка и бум при реалната дистанция. Изравни сила в прослушването и избери по разбираемост.",
  "Говорителят сменя якето с риза, която шумоли при допир.",
  "Тествай ново място за петличката или използвай близък бум и избери след реален запис.",
  "Микрофонът е част от сцената и гардероба. Мониторингът продължава след смяна на дрехите.",
  "Повиши чувствителността на камерата, за да компенсираш далечния микрофон.")

L("pv05-03", "Резерв за гласа без клипинг", "Ще настроиш входно ниво, ще слушаш пиковете и ще знаеш какво 32-bit float може и не може да спаси.",
  "Една силна дума удря тавана на записа; шумоподтискането няма как да върне отрязаната сричка.",
  "Дай запас за най-силната очаквана реплика и прослушай пробата от началото до края.",
  "Входният gain определя колко силен сигнал стига до записващата верига; ако аналогова част или безжичен предавател претовари, по-късен файлов формат не връща изгубеното. 32-bit float записващи устройства могат да дадат допълнителна гъвкавост при обработка, но работят в границите на целия хардуерен път.",
  "Помоли говорителя да произнесе реална силна реплика, не тихото „едно, две“. Прослушай и гледай пиковете, включително когато се смее или вика. Ако включиш safety track или втори канал на по-ниско ниво, увери се, че той записва отделно и наистина може да се използва. Не наричай тази система „Log аудио“: при звук важният въпрос е къде се получава клипинг.",
  ["Провери захранване, вход и място на микрофона.", "Настрой запаса по най-силната реална реплика.", "Запиши и прослушай силен и тих пасаж.", "Провери резервния канал и запази настройката преди интервю."],
  "Човек говори тихо в началото, после разказва развълнувано. Първите проби са добри, но при силната фраза звукът пука.",
  "Намаляваш плъзгача в монтажа и обявяваш отрязаната фраза за поправена.",
  "Върни входното ниво на записващото устройство или на предавателя, направи нов силен тест и провери резервен канал.",
  "Силната дума е без плосък отрязан пик и без чуваемо пращене; тихият пасаж остава използваем.",
  "32-bit float не оправя микрофонен капсул или предавател, който се претоварва преди файла.",
  "Запиши проба с тих говор, силна дума и смях. Върни се към оригиналния файл, не към обработен превю клип, и прослушай с паузи.",
  "Интервюто се мести до шумна машина и човекът започва да говори по-силно.",
  "Настрой входа и позицията наново по новата силна реплика, прослушай през слушалки и провери резервния запис.",
  "Предвиждай най-силния момент. Оставеният запас е евтин, изгубената сричка е скъпа.",
  "Пиши „Log аудио“ в инструкциите и разчитай файловият формат да възстанови клипинг.")

L("pv05-04", "Тихо място не значи добра акустика", "Ще оцениш шум и отражения и ще подбереш място за разбираем глас.",
  "Празна тиха зала звучи като тунел, докато малък шумен офис може да даде по-четима реч.",
  "Гледай едновременно съотношението на гласа към шума и колко дълго отекват думите.",
  "Големите голи повърхности връщат речта към микрофона. Мека мебел, завеси и близък микрофон често подобряват разбираемостта. Изключването на климатик може да помогне само ако е позволено и безопасно за мястото.",
  "Направи проба със същия човек и микрофон в две възможни позиции. Пази разстоянието до устата сравнимо и не оценявай по сила на плейъра. Отбележи периодични звуци като каса, превозно средство или хладилник. Ако шумът не може да се спре, търси място, където близкият глас преобладава и където имаш контрол върху паузите.",
  ["Слушай постоянното и периодичното в две локации.", "Запиши една и съща фраза от еднаква дистанция.", "Прослушай думите и паузите при изравнена сила.", "Избери място и уговори контрол над непредвидимия шум."],
  "Снимаш лекар в коридор и в кабинет. Коридорът е по-тих на слух, но гласът се връща от стените.",
  "Избираш коридора само по измереното ниво на фонов шум.",
  "Сравни пробите за разбираемост; избери кабинета или намери по-близка позиция и меки повърхности.",
  "Слушател разбира тихите окончания и на двата вида думи; паузите не звучат като отделна стая.",
  "Не покривай пожарно оборудване и не прекъсвай вентилация без разрешение и оценка на място.",
  "Запиши тест „една фраза + пет секунди пауза“ в две стаи. Провери отражението в края на думите и фоновите цикли.",
  "Планираното помещение не е достъпно и остава само кух коридор.",
  "Доближи микрофона, промени ориентацията и ограничи кадъра до по-акустично защитено място; повтори теста.",
  "Гласът трябва да работи и на телефонен говорител, не само на студийни слушалки.",
  "Добави дебел килим извън мястото на отражение и приеми, че всяко ехо е решено.")

L("pv05-05", "Voiceover: запис и обработка без пластмасов глас", "Ще запишеш чист глас зад кадър и ще обработиш шума, без да изтриеш сричките.",
  "Гласът е записан в килер без шум, но дишането и дрехите звучат по-силно от текста.",
  "Качественият voiceover започва от текст, тиха сцена, постоянна дистанция и няколко контролни дубъла.",
  "Постави микрофона леко извън директната струя въздух и използвай поп филтър при нужда. Маркирай позицията на човека и говори със същата енергия. Запиши проба и тишина на място.",
  "В монтажа първо избери най-ясния дубъл и сглоби естествени паузи. Ползвай шумоподтискане умерено; силна обработка може да изяде съгласните и да остави метален оттенък. Компресията изравнява големите разлики, но не замества позицията на микрофона. Слушай на слушалки и на обикновен телефон, като сравняваш еднаква крайна сила.",
  ["Прочети текста на глас и махни неудобните думи.", "Маркирай позиция, направи проба с нормална интонация.", "Избери дубъл и почисти очевидните шумове.", "Експортирай и провери паузите и разбираемостта на телефон."],
  "За реклама на сладкарница имаш 30 секунди глас. Дубъл 1 е чист, но бърз; дубъл 2 е по-естествен, но има една шумна глътка.",
  "Пускаш агресивен denoise върху целия дубъл 2 и изтъняваш всички съгласни.",
  "Избери естествения дубъл, почисти локално глътката или презапиши изречението при същата позиция.",
  "В телефонния експорт думите и тишината звучат естествено и няма метално „плуване“ на гласа.",
  "Формули за еднакъв EQ или LUFS не са универсална настройка за всеки говорител и всяка платформа.",
  "Направи две кратки версии: без обработка и с умерена обработка. Изравни силата при слушане, за да не бъркаш „по-силно“ с „по-добре“.",
  "Клиентът променя последното изречение след като цялата озвучка е записана.",
  "Презапиши изречението с еднаква позиция, помещение и тон; сравни с двете съседни реплики.",
  "Пази няколко секунди истинска тишина от помещението за естествени монтажни преходи.",
  "Повиши компресията, за да направиш тихите грешки еднакво силни с правилните думи.")

L("pv05-06", "Синхрон между отделен звук и картина", "Ще съчетаеш външен запис и видео, ще откриеш отместване и ще провериш дълъг дубъл.",
  "Началото е синхронно, а след половин час устните вече изпреварват гласа.",
  "Създай ясен общ маркер за записите и провери синхрона и в началото, и в края.",
  "Пляскане в кадър оставя видим и звуков пик; scratch audio от камерата също помага при синхронизиране. Поддържай отделните файлове организирани по дубъл, устройство и време.",
  "При дълги записи може да има дрейф заради различни часовници, променлива кадрова честота или грешно интерпретирани настройки. Не го поправяй само с преместване на целия аудио клип, ако началото е наред, а краят не е. Проверявай говорни съгласни на поне две далечни места във времевата линия и при нужда подготви коректен работен формат/настройка.",
  ["Пусни външен рекордер и камера, после направи видим маркер.", "Кръсти и архивирай файловете по дубъл.", "Синхронизирай началото по маркера или камерата.", "Провери говор в началото и края на дългия клип."],
  "40-минутен разговор от телефон и външен рекордер започва точно, но след 35 минути устните не съвпадат.",
  "Местиш целия звук с две рамки и разваляш началото.",
  "Провери дали телефонът е записал с променлива кадрова честота и дали проектът интерпретира файловете правилно; направи контролирано съвместимо копие при нужда.",
  "Съгласните съвпадат на няколко места през целия запис; оригиналите остават непокътнати.",
  "Пляскането фиксира начална точка, не гарантира липса на дрейф по цялата дължина.",
  "На копие от интервюто постави маркери при първата, средната и последната ясна съгласна. Сравни устните на реален експорт.",
  "Оказва се, че камерата няма използваем scratch audio.",
  "Използвай видимия маркер или времеви бележки и провери няколко говорни момента; не разчитай на автоматичен waveform match.",
  "Подреди файловете преди да режеш. Ако ги преименуваш след монтажа без връзка към оригинала, създаваш нов проблем.",
  "Изрежи всяка неудобна реплика и скрий липсата на синхрон с музика.")

L("pv05-07", "Музика с проверени права за точния проект", "Ще провериш лиценз, платформи и условия преди да сложиш музика под клиентско видео.",
  "„Без copyright“ в заглавието на чужд клип не е договор за рекламата на клиента.",
  "Свободно за слушане, безплатно за изтегляне и разрешено за търговска употреба са различни неща.",
  "Запиши кой държи правата, кой лиценз е купен или предоставен, за коя платформа, срок, територия и употреба важи. Пази фактура или текст на условията към конкретната версия на видеото.",
  "Музика от библиотеката на една платформа може да има правила само за тази платформа; прехвърлянето на клипа във Facebook или реклама може да изисква отделно разрешение. При Creative Commons провери точния вариант и изискваното посочване на авторство; договорът на платена библиотека също може да изключва реклами или препродажба. Когато правата са неясни, използвай проследим лиценз или собствена музика, не се осланяй на тестово публикуване.",
  ["Опиши къде и как клиентът ще използва видеото.", "Провери конкретния лиценз и страната, която го дава.", "Запази условията и документа към проекта.", "Прегледай финалната музика и употреба преди предаване."],
  "Видео за сладкарница тръгва в YouTube и след седмица клиентът иска платена реклама в Instagram със същия файл.",
  "Казваш, че щом YouTube не е свалил видеото, музиката е свободна за всички канали.",
  "Провери дали лицензът покрива платена реклама и другата платформа; ако не, смени музиката или придобий нужните права.",
  "В папката на проекта има документ за точната композиция, лицензополучател, версия и планирани канали.",
  "Условията на платформите и библиотеките се променят. Проверявай действащите условия при всеки нов канал или употреба.",
  "Подготви таблица само за себе си: композиция, източник, дата, лиценз, клиент, платформи, платена употреба и доказателство. Не изпращай файл с неясен статус.",
  "Клиентът иска да прожектира видеото на събитие, извън първоначално посочените канали.",
  "Провери договора за тази употреба преди прожекция; при липса на покритие осигури друг лицензиран вариант.",
  "YouTube Audio Library има собствени условия и някои тракове изискват атрибуция; Creator Music има ограничения на приложимостта. Провери официалните условия: https://support.google.com/youtube/answer/3376882",
  "Напиши „music by ...“ в описанието и смятай, че така автоматично получаваш лиценз.")

L("pv05-08", "Финален проект: минута, която се разбира без субтитри", "Ще запишеш и предадеш 60 секунди реч със стабилен звук, проверен синхрон и проследима музика.",
  "Красивият финал не спасява видео, в което едно ключово изречение е неразбираемо.",
  "Крайният тест е зрителят да разбере думите при нормално слушане; оценявай оригинала, монтажа и експорта отделно.",
  "Запиши разговор с реални шумове от мястото, близък микрофон и проверен входен запас. Избери най-разбираемите дубъли, запази естествени паузи и добави музика само ако не конкурира речта и имаш подходящи права.",
  "Провери началото, средата и края на файла на слушалки и на обикновен телефон при нормална сила. Не приемай числова loudness цел като универсално правило за всички платформи: виж изискването за конкретната доставка и провери, че няма клипинг. Ако субтитрите са нужни за достъпност, те допълват гласа, а не заместват липсващи думи в звука.",
  ["Запиши целта, канала и правата за музика.", "Направи аудио проба и 60-секунден запис със запас.", "Монтирай за разбираемост и провери синхрон.", "Изнеси и прослушай финала на телефон и слушалки."],
  "Минутно интервю за местен бизнес има правилно лице и две камери, но на 38-ата секунда врата покрива името на услугата.",
  "Оставяш дефекта, защото надписът на екрана казва същото.",
  "Избери чист дубъл, презапиши ключовото изречение при същата среда или използвай честен монтаж, който не подменя смисъла.",
  "Без да гледаш екрана се разбира кой говори, какво предлага и каква е ключовата фраза; музиката има проверен лиценз.",
  "Шумоподтискането не може да възстанови информация, напълно покрита от удар или клипинг.",
  "Пусни финала на човек, който не познава темата, без да му показваш кадъра. Нека повтори ключовото послание; ако не може, поправи проблема в аудиото.",
  "Клиентът премахва музиката за вторична версия на видео реклама.",
  "Изнеси вариант без музика и провери паузите, речта и фоновия шум отначало; не приемай, че смесването остава същото.",
  "Пази отделни оригинални файлове, проект и финален експорт. Така след месец можеш да промениш музика или реплика без да разрушиш звука.",
  "Нормализирай всичко до максимума и приеми, че по-силно значи по-ясно.")


# Модул 6: документите и хората са част от снимането, не пречка след него.
L("pv06-01", "Предпродукция: какво трябва да е решено преди терен", "Ще направиш кратък план с цел, хора, място, права и проверим резултат.",
  "Снимачният ден се проваля не заради камерата, а защото никой не знае кой отключва обекта.",
  "Напиши минимален работен документ: за кого е видеото, къде ще се ползва, кой взема решения и какъв резултат трябва да се види.",
  "Една страница стига, ако съдържа контакти, адрес, времеви прозорец, разрешения, резервно място и списък с нужни кадри и звуци. Раздели „потвърдено“ от „чака отговор“.",
  "Не започвай с изреждане на техника. Изясни кои твърдения трябва да бъдат проверени от клиента, дали участниците знаят къде ще се публикува видеото и кой разрешава достъп. Запиши какво е забранено за показване: лични данни, лица, продукти, търговска тайна. Когато има неизвестно, сложи собственик и срок за решение преди началото на снимките.",
  ["Определи цел, употреба и критерий за приемане.", "Потвърди участници, достъп, условия и права.", "Опиши задължителните кадри, звук и резервен вариант.", "Позвъни предния ден и затвори всички критични неизвестни."],
  "Местна работилница иска кратко видео за процеса. Майсторът идва след 10 ч., машината работи само в 9 ч., а никой не е изяснил дали може да се снима клиентски продукт.",
  "Пристигаш с готова shot list и започваш да снимаш без разрешения и без работещ процес.",
  "Потвърди отделно достъп, времето на машината и разрешението за конкретния продукт; промени графика преди тръгване.",
  "В плана има човек за контакт и отговор за всеки критичен въпрос; задължителните кадри могат да се заснемат.",
  "Една страница не замества договори и изискванията на организацията; тя показва какво още трябва да бъде потвърдено.",
  "Създай истински план за близък обект с три колони: потвърдено, неизвестно, кой да реши. Не изтривай неизвестните с предположение.",
  "Вечерта преди снимките човекът за контакт не потвърждава достъпа.",
  "Използвай резервното място или промени часа след писмено потвърждение; не пристигай с надежда, че някой ще отключи.",
  "Добрата подготовка е скучна само когато е свършена. На терен тя купува време за истинските реакции.",
  "Остави правата и достъпа за след снимките, за да не забавяш екипа.")

L("pv06-02", "Сценарий или свободен разговор?", "Ще избереш начин на говорене според точността на фактите и характера на човека.",
  "Човекът чете без да диша; ако го оставиш да импровизира, забравя най-важното условие.",
  "Раздели задължителните факти от начина, по който говорителят ги произнася.",
  "Напиши опорни точки за естествен разговор и отделен списък с точни числа, условия, имена и юридически одобрени фрази. Телепромптерът помага за точен текст, но изисква репетиция и темпо.",
  "Провери как говорителят разказва темата на приятел без камера. Ако историята е силна, вземи разговорния вариант и допълни необходимите факти с кадри или графика след проверка. Ако обещанието е строго формулирано, заснеми точното изречение отделно. Не принуждавай човек да казва твърдение, което не е потвърдено от отговорния в организацията.",
  ["Отбележи точните факти и отговорния за тях.", "Запиши свободен пробен отговор.", "Избери опорни точки или точен текст според грешките.", "Сними и провери съдържанието преди финалния монтаж."],
  "Собственичка на салон говори увлекателно за услугата, но казва „винаги безболезнено“, което клиентът не може да гарантира.",
  "Оставяш силната реплика, защото звучи убедително, без да провериш обещанието.",
  "Запази естествения тон, но попитай какво може да се твърди точно и презаснеми частта с провереното условие.",
  "Одобрените факти присъстват; изказът е естествен и няма неподкрепени абсолютни обещания.",
  "Импровизация не дава право да измисляш факти, а точният сценарий не гарантира естествена игра.",
  "Заснеми два 15-секундни варианта на една мисъл: дословен и по опорни точки. Провери едновременно точност и разбираемост.",
  "Клиентът добавя законово изисквана фраза накрая.",
  "Запиши я отделно точно и с разбираемо темпо, после провери с отговорния човек как стои в целия монтаж.",
  "Говорителят не трябва да носи цялото съдържание на гръб: видими действия и проверена графика могат да обяснят част от него.",
  "Помоли говорителя да научи още две страници наизуст и ускорете четенето.")

L("pv06-03", "Оглед на мястото: светлина, звук, фон, достъп", "Ще огледаш локация с кратка проба и ще предотвратиш скрити пречки.",
  "Снимка на помещението изглежда чудесно, докато не чуеш компресора до стената.",
  "Огледът е снимана и прослушана проверка при часа на бъдещата работа.",
  "Тествай къде ще застане човекът, откъде идва светлината, как звучи гласът, какво се вижда на заден план и къде минават хората. Забележи контакти, ограничения за статив и достъп до тоалетна или почивка.",
  "Променяй един фактор в пробите: позиция, фон, микрофон. Кратко видео с реч разкрива повече от галерия със снимки. Провери дали фирмени знаци, документи на стена, клиентски адреси или чужди лица ще попаднат в кадър. Планирай кога мястото се освобождава и как ще оставиш оборудването без да блокираш работа.",
  ["Уговори оглед в сравним час и получи достъп.", "Запиши кадър с реч на планираното място.", "Провери фон, шум, светлина и маршрут на кабелите.", "Потвърди с домакина какво може да се мести или показва."],
  "Кафене разрешава снимки сутрин. Красивият ъгъл от снимките е до хладилна витрина, която се включва внезапно.",
  "Избираш ъгъла само по снимката и оставяш проверката за след първия въпрос.",
  "Направи говорна проба при работеща витрина, намери алтернативен ъгъл или уговори контролирана пауза.",
  "Избраният кадър и звук остават използваеми в реалното работно време; достъпът и преместванията са потвърдени.",
  "Един оглед не предвижда всяка промяна: планът включва резервна позиция и контакт на място.",
  "Запиши три проби по 10 секунди на възможни места и сравни тихия глас, лицето и фона. Остави отбелязана резервна позиция.",
  "В деня на снимките предвидената маса е заета от клиент.",
  "Премини към потвърдения резервен ъгъл, направи нова аудио проба и не мести клиент без съгласие.",
  "Най-скъпият избор на локация е този, който не е бил слушан.",
  "Използвай повече шумоподтискане след монтажа вместо проба.")

L("pv06-04", "Снимачната чанта: комплект срещу отказ", "Ще подготвиш минимален комплект, който има захранване, запис и проверен резерв.",
  "Резервният обектив е в чантата, но резервна карта и батерия липсват.",
  "Подреждай багажа около видовете провал: няма захранване, няма запис, няма звук, няма безопасен монтаж.",
  "Списъкът за конкретния проект включва заредени батерии, празни проверени карти, микрофон и слушалки, надежден монтаж, кабели и маркировки. Провери съвместимостта и състоянието, а не броя предмети.",
  "Направи пробен път от камерата до компютъра: запис, възпроизвеждане, копие. Маркирай коя карта е използвана и не форматирай заснет материал, преди да имаш проверени копия. Постави дребните резервни части там, където можеш да ги намериш по време на интервюто; списъкът работи само ако се използва преди излизане и при прибиране.",
  ["Преброй критичните режими на отказ за този проект.", "Провери батерии, медии, микрофон и закрепване с кратък запис.", "Подреди основно и резервно средство за всяка критична функция.", "Отметни комплекта преди тръгване и след края на деня."],
  "На снимки извън града без магазин наблизо картата на камерата се запълва след първия час.",
  "Изтриваш по-старите добри кадри, защото имаш втори обектив, но не и проверено копие.",
  "Спри, осигури нова проверена медия или копирай и провери на поне две места по плана; не изтривай единствения оригинал.",
  "Остават четими оригинали и има носител за следващата сцена, без да се унищожава непроверен материал.",
  "Двойният слот не замества проверено копие извън устройството, а резервните части трябва да са съвместими.",
  "Опаковай чантата за реално интервю, после симулирай една липса: батерия, кабел или карта. Измери дали можеш да продължиш без риск за материала.",
  "Излиза, че резервният рекордер използва друг тип захранване.",
  "Провери реалните батерии и кабели за него преди тръгване; ако липсват, планирай друг проверен резерв.",
  "Надеждната чанта е карта на решенията при провал, не списък на притежаваното оборудване.",
  "Купи още обективи вместо да провериш записващата верига.")

L("pv06-05", "Какво да не купуваш още", "Ще решиш дали нова техника решава измерен проблем или само прикрива слаб процес.",
  "Новата камера пристига, но клиентът пак не разбира гласа в рекламата.",
  "Назови дефекта от предишен проект и покажи как покупката ще го намали при същите условия.",
  "Ако проблемът е говор отдалеч, близък микрофон и тиха стая могат да помогнат повече от нова камера. Ако видеото губи кадри при презапис, по-добра организация на медията е по-належаща от светлина за фон.",
  "Направи малка проба: снимай една сцена с настоящия комплект, промени само начина на работа и виж дали провалът изчезва. Наем или заем на техника за едно снимане може да покаже разликата преди покупка. Сметни и допълнителните разходи: батерии, носители, стойки, транспорт, време за обучение. Не купувай спецификация, която няма място в този работен процес.",
  ["Опиши повторящ се дефект с конкретен файл.", "Пробвай поправка чрез позиция, светлина, звук или процес.", "Ако не стига, тествай наета/заемана техника при същите условия.", "Реши покупка според измеримата промяна и общия разход."],
  "Фрийлансър снима интервюта в малки офиси. Купува по-скъп обектив, но отговорите още звучат кухо.",
  "Поръчва нова камера, без да е сравнил по-близък микрофон и друго място.",
  "Направи A/B звук на същото интервю с близък микрофон; инвестирай само в решението, което премахва реалния дефект.",
  "В сравними файлове проблемът е по-малък и можеш да обясниш кое действие е причината.",
  "Някои задачи наистина изискват нова техника; отказът от покупка не е правило, а решение след проба.",
  "Извади три най-лоши кадъра от минали работи и запиши конкретен корен на проблема за всеки. Вложи бюджета първо там, където причината е доказана.",
  "Нов клиент иска заснемане при светлина, която настоящият комплект не може да поддържа.",
  "Тествай нает подходящ източник на място, сметни повторяемостта на задачата и едва тогава избери покупка.",
  "Разходът за техника е оправдан, когато знаеш как ще провери клиентът разликата във финалния файл.",
  "Избери техника по най-високата рекламирана резолюция.")

L("pv06-06", "График на снимачния ден със запас", "Ще направиш график, който отчита смени, почивки, проби и риск от закъснение.",
  "На хартия има 12 кадъра за час. На терен всеки пренос на лампа взема десет минути.",
  "Групирай кадрите по място и подготовка, а не само по реда във финалното видео.",
  "Отдели време за пристигане, настройка и проба, действителните дубли, промени на осветление и звук, почивки, копиране и прибиране. Посочи кога ключов човек или локация не са налични.",
  "Постави задължителните кадри преди допълнителните и определи момент за решение „свиваме обхвата“. При разминаване не съкращавай проверката на звук и безопасното прибиране; махни или комбинирай най-малко важен план. Изпрати часовете на участниците като реални прозорци, не като гаранция за минута по минута.",
  ["Запиши фиксираните часове на хора, място и светлина.", "Групирай кадри по еднаква установка.", "Добави проби, почивки, копиране и буфер.", "Определи кои кадри отпадат първи при закъснение."],
  "В сладкарница фурната е достъпна сутрин, собственичката — по обед, а клиентите влизат следобед. Графикът от сценария започва с интервю.",
  "Следваш монтажния ред на сцените и изпускаш единственото време за печене.",
  "Премести процеса при фурната в ранния прозорец, подготви звук за интервюто преди обед и остави буфер за клиенти.",
  "Задължителните кадри в ограничени прозорци са заснети; има време за проверка на файловете и прибиране.",
  "Буферът не е оправдание да обещаеш повече кадри, отколкото мястото и хората позволяват.",
  "Направи план по часове за реален бизнес. Постави един неочакван проблем от 20 минути и покажи кой незадължителен кадър отпада.",
  "Ключовият човек закъснява с половин час.",
  "Използвай времето за предметни кадри и звук от мястото, после актуализирай графика с нов прозорец за човека.",
  "Графикът дава решения, когато реалността се намеси; без приоритети е само красива таблица.",
  "Прехвърли всички забавени задачи в края и обещай, че ще се заснемат без нова смяна.")

L("pv06-07", "B-roll, който покрива конкретен монтаж", "Ще направиш списък с кадри, които обясняват действие и дават честни монтажни преходи.",
  "Имаш десет красиви детайла на инструменти, но нито един кадър на самата работа.",
  "B-roll трябва да доказва казаното и да покрива нужните преходи, не да пълни време.",
  "За всяко твърдение запиши видимо действие: начало, изпълнение и резултат. Вземи широк, среден и близък план само когато те дават различна информация. Отбележи необходимия звук на действието.",
  "Планирай посоката на движенията и предметите между плановете: от коя ръка се взема материалът, къде се поставя и кога процесът се променя. Не снимай чужди лица или чувствителни екрани само защото са удобен фон. След първия снимачен блок отвори материалите и виж кой конкретен срез още няма покритие; допълни го, докато човекът и обектът са налични.",
  ["Разпиши ключовите твърдения или движения.", "За всяко запиши начало, действие, резултат и нужен звук.", "Сними различни информативни дистанции и посоки.", "Прегледай материала и попълни липсващите монтажни връзки."],
  "Майстор казва, че всяка поръчка се тества. Заснети са красиви рафтове и усмивка, но няма кадър на самия тест.",
  "Покриваш репликата с произволен кадър на инструмент и внушаваш проверка, която не се вижда.",
  "Заснеми реалния тест: подготовка, измерване и резултат, със съответния звук и разрешение.",
  "Зрителят може да посочи на кадър действието, за което говорителят разказва.",
  "B-roll не бива да инсценира доказателство за услуга, която не е извършена.",
  "Вземи тридесет секунди от реален процес и напиши точно три липсващи визуални връзки, които монтажът изисква. Снимай само тях.",
  "Процесът вече е приключил и няма разрешение за повторение.",
  "Използвай наличните честни кадри, промени формулировката на твърдението или отбележи липсата за нов снимачен ден.",
  "Листът за B-roll е договор между това, което се казва, и това, което действително може да бъде показано.",
  "Вмъкни красив кадър от друга поръчка и го представи като същия тест.")

L("pv06-08", "Колко дубъла стигат?", "Ще спираш след проверен работещ дубъл и ще знаеш кога допълнителният има смисъл.",
  "Десетият дубъл е изтощен, а първият е бил добър — само че никой не го е проверил.",
  "Преди повторение назови конкретния дефект: факт, тон, кадър, звук или движение.",
  "Първият дубъл често показва естествена енергия; вторият може да изчисти факт или движение. Няма магически брой повторения. Кратко възпроизвеждане със звук спестява повторения без цел.",
  "Раздели „може да се монтира“ от „идеален“. Ако имаш чиста пълна фраза и нужните преходи, снимай вариант само с друга интонация или по-кратък отговор, когато проектът го иска. Ако проблемът е засядане от напрежение, промени въпроса или направи пауза, вместо да повтаряш същата команда. Маркирай успешните дубъли по файл и секунда.",
  ["Определи какво трябва да се види и чуе.", "Сними един пълен дубъл и го прослушай.", "Назови конкретния проблем, преди да поискаш повторение.", "Сними целеви дубъл или продължи, ако материалът вече покрива задачата."],
  "Пекар отговаря добре за процеса на втория дубъл. Режисьорът иска още пет „за всеки случай“, но човекът започва да говори механично.",
  "Повтаряш фразата докато изчезне естественият тон, без да провериш втория файл.",
  "Спри и прегледай втория дубъл със звук; ако той работи, премини към действие и детайли.",
  "Има маркиран годен отговор с точен факт и чист звук, а участникът не е изтощен.",
  "При сложни движения или неповторимо събитие може да са нужни повече камери/покритие; броят дубъли сам по себе си не дава гаранция.",
  "Симулирай три дубъла на кратка демонстрация. След всеки назови един дефект и реши с конкретен критерий дали повтаряш.",
  "След паузата откриваш, че най-добрият дубъл има щракване в ключовата дума.",
  "Поискай целеви повторен отговор при същата обстановка и проверен микрофон, вместо да повтаряш целия разговор.",
  "Кажи на човека какво вече работи и какво точно искаш да промениш.",
  "Снимай фиксирано поне осем дубъла на всяка реплика.")

L("pv06-09", "План Б за светлина, звук и достъп", "Ще подготвиш решения за трите отказа, които могат да прекратят снимачния ден.",
  "Небето се затваря, шумна машина тръгва и отговорният човек напуска — това не е необичаен ден.",
  "Рискът става управляем, когато има ранно предупреждение, собственик на решение и резервна сцена.",
  "Запиши критичен риск, вероятен симптом, действие и кой дава разрешение. За светлина може да има резервна позиция, за шум — друг времеви прозорец, за достъп — алтернативен човек или кадър.",
  "Определи условия, при които снимането спира: опасен кабел, липса на право за локация, невъзможен за разбиране звук, непотвърдени права за лице. Не решавай чужди разрешения с подпис „после“. Ако се включи резервният план, съобщи на клиента каква информация или кадри ще се променят, преди да продължиш.",
  ["Назови три най-скъпи провала за проекта.", "Задай измерим симптом и човек за решение.", "Избери безопасна алтернатива преди снимачния ден.", "При проблем спри, потвърди промяната и направи нова проба."],
  "Видео в работилница трябва да покаже машина. На терен се оказва, че демонстрацията днес не е разрешена по съображения за безопасност.",
  "Пускаш машината „само за десет секунди“, защото вече е обещана в сценария.",
  "Спри този кадър; потвърди друга безопасна демонстрация или пренасрочи и съгласувай промяната с клиента.",
  "Няма заснето опасно или неразрешено действие; клиентът знае какво ще замести липсващия кадър.",
  "Резервният план не разрешава нарушаване на правилата на мястото или правата на участниците.",
  "За следващия си снимачен ден напиши три реда „ако X, тогава Y“ и провери дали Y наистина е възможно с наличните хора и време.",
  "План Б изисква локация, която клиентът не може да предостави.",
  "Отбележи плана като невалиден и потърси вариант, който може да бъде потвърден предварително.",
  "Риск без изпълним отговор още е неизвестно. Запиши го честно, преди да обещаеш краен срок.",
  "Разчитай на софтуер, за да превърне опасна или несъществуваща сцена в доказателство.")

L("pv06-10", "Репетиция на терен с истинските условия", "Ще направиш кратка генерална проба с човек, камера, звук и движение преди основния запис.",
  "Празният кадър е перфектен; щом човекът седне, микрофонът търка сакото и ръката закрива продукта.",
  "Репетирай действието, което ще снимаш, а не празна сцена с красив фокус.",
  "Включи истинския човек, облекло, предмет, звук и път на движение. Провери във видеото начало, ключова реплика и край на действието. Не е нужно дълго разиграване, но пробата трябва да покаже какво може да провали кадъра.",
  "Прегледай записа веднага и назови само проверимите проблеми: дреха шуми в определен момент, лице излиза от светлината, ръка закрива етикета. Промени позиция, звук или движение и повтори същата проба. Ако сцената включва неповторим момент, направи съкратена репетиция без да го изхабяваш и подготви резервен план.",
  ["Постави участник и предмет в истинските им позиции.", "Пусни кратко пълно действие със запис на звук.", "Прослушай и погледни най-трудния момент.", "Поправи една конкретна причина и повтори пробата."],
  "Шеф-готвач показва пълнене на буркани. При първа проба етикетът се обръща от камерата, а метален капак удря микрофона.",
  "Казваш „ще оправим в монтажа“ и започваш цялата серия буркани.",
  "Промени страната на поставяне и позицията на микрофона; потвърди с втора кратка проба преди неповторимата работа.",
  "На тестовия файл се вижда етикет и се чува обяснението без удар; движението може да се повтори.",
  "Репетицията не трябва да нарушава безопасност или да изразходва единствения наличен продукт без съгласие.",
  "За реална демонстрация сними 15-секунден пробен ход и сравни кадъра преди/след промяната. Запиши какво е довело до подобрението.",
  "Продуктът може да се използва само веднъж и проба с него не е възможна.",
  "Репетирай с празна опаковка или заместител със сходен размер; осигури достатъчно камери/покритие за единствения истински дубъл.",
  "Добрият снимачен ден започва със запис, който спокойно можеш да изтриеш — след като си научил от него.",
  "Сменяй пет настройки наведнъж и запомни кое точно е помогнало.")

L("pv06-11", "Човек пред камера: свали напрежението с работа", "Ще помогнеш на притеснен говорител да каже смисъла със свой глас, без да му диктуваш личност.",
  "Казваш „отпусни се“ и човекът става още по-напрегнат.",
  "Дай проста задача, кратък въпрос и право на повторение; обясни какво ще използваш от записа.",
  "Започни с нещо, което човекът прави всеки ден, или с лесен конкретен въпрос. Пази малък брой хора около камерата и дай време за пробен дубъл без публика. Кажи „Това начало работи, нека повторим последната мисъл по-бавно“, вместо обща оценка на човека.",
  "Провери дали напрежението не идва от реално опасение: неясна употреба на видеото, непотвърдени фирмени твърдения или липса на съгласие. Реши причината, не я лекувай с комплименти. Дай на говорителя възможност да не отговори на въпрос и да уточни казаното, без да обещаваш право да пренапише честен факт след монтажа.",
  ["Обясни употреба, време и как протича записа.", "Започни с лесно конкретно действие или въпрос.", "Дай една точна обратна връзка след проба.", "Провери смисъла и звука преди да продължиш."],
  "Счетоводителка трябва да обясни нова услуга. На четвъртия дубъл чете все по-бързо и бърка условие за цена.",
  "Повтаряш „по-естествено!“ без да ѝ кажеш коя част вече е добра.",
  "Спрете за минута, уточнете точната цена и условие, попитай я за реален клиентски случай и вземи една кратка мисъл наведнъж.",
  "Чува се провереното условие в естествена реч и говорителят знае кои отговори ще бъдат използвани.",
  "Не всеки човек се чувства удобно пред камера; ако продължава да не иска участие, смени формата или говорителя.",
  "Направи два пробни въпроса на познат човек: абстрактен и за реален случай. Прегледай с него къде се появява конкретен отговор.",
  "Човекът казва, че не желае да говори за личен клиентски случай.",
  "Премини към анонимизиран процес или друг пример, който той доброволно може да обясни.",
  "Уважението не забавя работата. То прави възможен кадър, в който човекът наистина говори.",
  "Промени текста тайно в монтажа така, че участникът да звучи по-уверено.")

L("pv06-12", "Интервю: въпросите, които дават истински отговор", "Ще формулираш въпроси, които извеждат действия, избори и проверими подробности.",
  "На „Как сте по-добри от конкуренцията?“ получаваш пет общи прилагателни и нито един кадър.",
  "Искай случай и действие: какво се случи, какво избрахте, какъв резултат наблюдавахте.",
  "Краткият въпрос оставя място за разказ. „Разкажи за последния клиент, на когото помогна“ дава по-добър материал от „Кажи, че сте най-добрите“. След конкретния случай попитай за доказателство, ограничение и какво не е проработило.",
  "Изслушай отговора докрай, не задавай втори въпрос върху първия. Отбележи фраза, която изисква проверка: число, срок, резултат или здравно/финансово обещание. Планирай покривни кадри за действията, които участникът описва. Когато отговорът е само лозунг, помоли за един конкретен ден, предмет или действие.",
  ["Запиши какво зрителят трябва да разбере.", "Задай кратък въпрос за реален случай.", "Попитай какво се вижда, как е проверено и какви са границите.", "Маркирай ключови факти за потвърждение и кадри за покритие."],
  "Производител на халва казва „качеството е в основата“. Трябва ти видео за реалното производство.",
  "Насочваш го да повтори лозунга с повече ентусиазъм.",
  "Попитай как днес проверяват една партида, какво виждат при грешка и кой взема решението да я спре.",
  "В отговора има конкретно действие и граница, които могат да се проверят и покажат.",
  "Не всяка история е публична; пази поверителността и провери кои примери могат да се разказват.",
  "Вземи общо рекламно твърдение от собствен сайт и направи от него три въпроса за конкретен случай, мярка и ограничение.",
  "Човекът започва да разкрива лични данни на клиент.",
  "Спрете, уточнете какво може да се каже и презаснемете с анонимен, позволен пример.",
  "Пет силни въпроса не са фиксиран шаблон: слушането между тях определя какво идва след това.",
  "Задай наведнъж три въпроса и после избери удобния отговор.")

L("pv06-13", "Естествено поведение с видима камера", "Ще снимаш реална работа, без да представяш режисирана сцена за случайно наблюдение.",
  "Когато хората видят камерата, започват да играят „работещи хора“ и забравят реалната задача.",
  "Дай време на участника да се върне към познатото действие и снимай истинския процес с ясни правила.",
  "Преди запис обясни коя дейност ще се снима и кой няма да попада в кадър. Не крий камерата като техника за „автентичност“. Избери по-дълъг статичен кадър, остави човека да работи и поддържай малък екип.",
  "Можеш да помолиш за повторение на действие за технически кадър, но не представяй повторението като доказателство за уникално събитие, което не се е случило. Запази последователност от началото до края и истински звук от работата. Ако присъствието на камера променя процедурата или нарушава безопасност, спри и адаптирай кадъра.",
  ["Уточни дейността и границите на снимане.", "Постави камерата така, че да не пречи на работата.", "Запиши цял цикъл на действие и собствен звук.", "Провери дали монтажът не внушава несъществуващ резултат."],
  "Майсторка опакова поръчка. Екипът иска тя да се усмихва към камерата при всяка стъпка, но така пропуска контролното теглене.",
  "Режисираш последователност, в която липсва реалната проверка, а после твърдиш, че е заснета.",
  "Остави реалния работен ред, заснеми тегленето и поискай отделен портретен кадър след приключване.",
  "Видеото показва реалната последователност и участниците знаят кога и защо са заснети.",
  "Реакцията „естествено“ не оправдава скрит запис на хора без подходящи права и контекст.",
  "Сними непрекъснати 30 секунди от доброволно показан процес и после монтирай 10 секунди без да сменяш причинно-следствения ред.",
  "По време на процеса влиза случаен клиент, който не е част от снимките.",
  "Спри или промени кадъра, така че клиентът да не бъде записван/публикуван без подходящо основание.",
  "Можеш да режисираш рамката и позицията, без да режисираш фалшив факт.",
  "Сложи скрита камера и после искай разрешения.")

L("pv06-14", "Снимане на деца: ясни граници преди кадъра", "Ще организираш детска сцена само след проверени правила, достъп и отговорен възрастен.",
  "Училището казва „всички са съгласни“, но няма яснота за реклама, съхранение и конкретните деца в кадър.",
  "Преди камерата провери с организацията правното основание, употребата, ограниченията и кой отговаря за всяко дете.",
  "Работи със списък кой може да се снима и за каква конкретна цел, даден от упълномощения организатор. Не записвай имена и излишни лични данни в кадър. Определи безопасни зони за деца извън камерата.",
  "При училища съгласието може да не е единственото или подходящото правно основание; организацията и нейният отговорник за данните трябва да определят условията. Същият кадър може да има различни правила за вътрешно използване и публична реклама. Не приемай, че общо разрешение за училищна снимка покрива клиентски клип. Изясни съхранение и изтриване, достъп до оригинали, надзор и право на отказ по приложимите правила.",
  ["Установи отговорен възрастен и правилата на организацията.", "Провери кои участници и употреби са разрешени.", "Подготви кадри, които не разкриват ненужни данни.", "Преди публикуване провери финалната версия и обхвата на разрешенията."],
  "НПО снима детска работилница. Има разрешение за вътрешен отчет, но по-късно иска публична платена реклама със същите лица.",
  "Приемаш вътрешното разрешение за достатъчно и изпращаш рекламата без нова проверка.",
  "Спри публикуването и поискай от организацията проверка на правното основание и обхвата за публична платена употреба; подготви вариант без разпознаваеми деца.",
  "За всяко лице и канал от финалния файл има потвърдено основание от отговорната организация; несигурните кадри не са публикувани.",
  "Въпросите за права на деца зависят от конкретните отношения и закон; редакторът не трябва сам да измисля правно основание.",
  "За учебен пример с условни лица направи таблица: вътрешен отчет, сайт, платена реклама. Отбележи кои употреби са потвърдени и кои чакат организацията.",
  "В залата влиза дете, за което няма потвърдено разрешение за запис.",
  "Насочи камерата към работа без разпознаваемо лице или изчакай организацията да изясни условията.",
  "Проверка: EDPB разглежда специално съгласието в училищни отношения: https://www.edpb.europa.eu/sites/default/files/files/file1/edpb_guidelines_202005_consent_en.pdf . Уточнявай случая с отговорното лице.",
  "Публикувай със замъглено лице, без да провериш дали и гласът, името или контекстът разпознават детето.")

L("pv06-15", "Достъп, одобрения и факти във фирмен запис", "Ще подготвиш права за мястото и проверени твърдения, преди да снимаш фирмено видео.",
  "Говорителят обещава „гарантиран резултат“, а логото на чужд клиент стои зад него.",
  "Раздели разрешение за място, участие на хора, използване на материали и проверка на публичните твърдения.",
  "Една фирма може да разреши снимки в офиса, без това да включва служители, клиентски документи, музика на заден план или чужди брандове. Запиши кой от компанията може да одобри всяка част.",
  "Създай кратък списък с факти, които трябва да се потвърдят: цена, срок, обхват, резултати и условия. Запиши датата и източника на потвърждение, както и какво остава неизвестно. Преди снимачен ден прибери видимите чужди данни и набележи къде в кадъра се появяват чужди знаци. При смяна на сценария поискайте ново одобрение за новото твърдение, не го „поправяйте“ с дребен надпис.",
  ["Запиши всички планирани публични твърдения.", "Определи собственик на фактите и разрешенията.", "Провери локацията за чужди хора, знаци и документи.", "Сними само потвърденото и изпрати фактическия монтаж за одобрение."],
  "Фирма за услуги казва, че работи с „над 500 клиента“, но никой не знае към коя дата е числото. На стена се вижда договор на друг клиент.",
  "Оставяш числото и документа в кадър, защото ще излезе бързо в социалните мрежи.",
  "Провери числото с отговорен човек и дата или го махни; прекадрирай така, че договорът да не попада във файла.",
  "Всеки проверим факт има източник и дата, а финалният файл не разкрива чужди данни.",
  "Одобрение на груб монтаж не създава автоматично права върху чужда музика или лични данни.",
  "Създай „лист на твърденията“ за 30-секундна реклама: факти, обещания, използвано лого и човек за одобрение. За непотвърдено остави празно.",
  "След снимките маркетингът добавя ново твърдение за най-ниска цена.",
  "Върни го за доказателство и одобрение с дата; без него не го поставяй в публичния файл.",
  "Вместо да искаш общо „одобрявам“, посочи на клиента точно какви факти и права той потвърждава.",
  "Сложи дребен надпис „резултатите може да варират“ и остави неподкрепения абсолютен текст.")

L("pv06-16", "Фирмен говорител без заучена реклама", "Ще изведеш ясна фирмена позиция от човек, който познава работата, и ще пазиш точността.",
  "Управителят знае всичко, но в кадър казва само „качество, професионализъм, отношение“.",
  "Попитай как фирмата работи в конкретен ден, после превърни отговора в една полезна за зрителя мисъл.",
  "Подготви до три цели: какъв проблем решава услугата, как протича работата и какво клиентът може да очаква. Поискай реален пример, в който самият говорител е взел решение.",
  "Проверявай дали фирмените фрази са истина за целия клиентски процес. Ако човекът започне да чете страница с суперлативи, спри и го попитай как би обяснил услугата на свой познат. Запиши кратки самостоятелни отговори и чисти начални и крайни изречения за монтаж. Когато чужд отдел трябва да одобри условия, използвай само потвърдените части.",
  ["Избери една конкретна зрителска нужда.", "Вземи реален случай и проверими действия.", "Запиши кратки отговори със собствени думи.", "Свери фирмените факти и изгледай целия монтаж с говорителя."],
  "Управител на малък хотел трябва да обясни какво става при късно пристигане. Сценарият казва само „винаги сме на разположение“.",
  "Оставяш абстрактното обещание, защото звучи добре на камера.",
  "Попитай за реалната процедура, час и начин на контакт; ако има условие, кажи го ясно и провери с екипа.",
  "Зрителят разбира какво да направи при късно пристигане и кои условия са потвърдени.",
  "Няма нужда всеки управител да играе актьор; полезността идва от конкретния процес.",
  "Сравни 20 секунди лозунги и 20 секунди конкретен отговор. Питай външен зрител кой вариант би му помогнал да вземе решение.",
  "Няма потвърден нощен телефон за връзка.",
  "Не го обещавай; остави потвърдените канали и поискайте актуална информация преди финала.",
  "Добрият фирмен говорител звучи като човек, който може да помогне, а не като написана секция „За нас“.",
  "Подложи отговора на тежък ефект и бърз монтаж, за да не личи липсата на конкретика.")

L("pv06-17", "Снимай себе си без да гадаеш кадъра", "Ще снимаш сам себе си с повторяем кадър, фокус, звук и проверен запис.",
  "Говориш убедително 20 минути, после откриваш, че фокусът е на рафта зад теб.",
  "При самозаснемане замести липсващия оператор с маркировки, контролен кадър и кратки проверки.",
  "Маркирай къде стоиш, заключи кадъра и провери фокус на истинското място на очите. Избери близък микрофон и прослушай проба. Използвай телефон или монитор за контрол, ако имаш, но не оставяй превюто да спира запис или изтощава батерия.",
  "Раздели текста на кратки мисли и оставяй секунди тишина преди и след всяка. След промяна на позиция, облекло или светлина повтори теста; грешка в един дубъл е по-евтина от грешка в цял снимачен ден. Ако устройството има ограничение на запис или време, провери го предварително на истинската продължителност.",
  ["Маркирай позиция, кадър и разстояние до микрофона.", "Запиши проба с движение и най-силната реплика.", "Възпроизведи файла и провери очи, глас и таймер.", "Снимай на къси сегменти и проверявай след всяка смяна."],
  "Предприемач снима курс сам. Премества стола след първата почивка и продължава; всички следващи клипове имат отрязана ръка.",
  "Разчиташ, че широкият кадър ще се поправи с автоматично прекадриране.",
  "Върни се към маркировката, запиши пробен кадър на стола и провери на възпроизведения файл.",
  "Очите са в фокус, ръцете и важният предмет се виждат, гласът е разбираем във всеки сегмент.",
  "Автофокус и автоматична експозиция може да работят, но трябва да се тестват при реалното движение.",
  "Сними три кратки сегмента с умишлена смяна на мястото между втория и третия; опиши коя проверка хваща разликата навреме.",
  "Слънцето изчезва след първия сегмент.",
  "Преоцени светлината, направи нов тест за експонация и баланс и запази контролен кадър за съвпадение.",
  "Самостоятелната продукция изисква повече дисциплина, не непременно повече техника.",
  "Провери само миниатюрата на екрана и изтрий тестовия файл без прослушване.")

L("pv06-18", "Финален проект: интервю с истински човек", "Ще планираш, снимаш и предадеш кратко интервю, което издържа проверка на факти, звук, права и монтаж.",
  "Силният финален въпрос не струва много, ако липсва право да използваш отговора или звукът е непригоден.",
  "Работи с реален доброволен възрастен участник, разрешено място и проверена употреба на видеото.",
  "Подготви едностраничен план с цел, въпроси и задължителни действия за B-roll. На терен запиши проба, кратък разговор, звук от мястото и действия, които действително илюстрират казаното. Не използвай деца за този учебен проект.",
  "Монтирай 60–90 секунди с ясна основна мисъл и поне един проверим конкретен случай. Прегледай всички числа, чужди лица, брандове и лиценз за музика. Сравни изходен и финален звук, провери синхрон и отвори файла на телефона, на който ще гледа публика. Пази оригинали и бележки за разрешенията; ако даден факт не може да бъде проверен, извади го или го върни за потвърждение.",
  ["Осигури участник, цел, права и конкретни въпроси.", "Направи проба и заснеми разговор плюс честен B-roll.", "Монтирай за смисъл, разбираем глас и верни факти.", "Провери експорта, правата и финалния файл на реално устройство."],
  "Интервю с пекар разказва как подготвя поръчки. Има жив отговор, но B-roll показва друга поръчка, а цената е казана без дата.",
  "Предаваш проекта като „готов“, защото картината е красива и музиката прикрива аудио грешките.",
  "Замени неточния B-roll с кадър от същия процес или махни внушението; потвърди цената с дата и преработи неразбираемата фраза.",
  "Външен зрител разбира кой, какво и как; твърденията и употребата са потвърдени, а речта е ясна без субтитри.",
  "Самооценката по чеклист не заменя действителна обратна връзка от зрител и отговорния за фактите.",
  "Пусни експорта на човек, който не познава бизнеса, и попитай какво е разбрал. После провери по отделен списък права, факти, звук, синхрон и честност на B-roll.",
  "След завършване участникът уточнява, че един кадър съдържа поверителен документ.",
  "Спри този експорт, премахни кадъра и предай проверена нова версия; актуализирай бележките за одобрение.",
  "Финалният файл е резултат от проверими решения на терен и в монтажа, не награда за отметнати страници.",
  "Приеми, че публикуването само по себе си доказва качество и налични права.")
